python -c 'import inspect
from more_itertools import last
p = inspect.signature(last).parameters["default_factory"]
assert p.kind == inspect.Parameter.KEYWORD_ONLY and p.default is None
def expect(kind, action):
    try: action()
    except kind: return
    raise AssertionError("expected " + kind.__name__)
calls = []
def factory():
    calls.append("called")
    return {"fresh": True}
assert last(iter([]), default_factory=factory) == {"fresh": True}
assert calls == ["called"]
calls.clear()
for value in (None, False, 0, []):
    assert last(iter(["head", value]), default_factory=factory) is value
assert calls == []
for fallback in (None, False, 0):
    assert last([], default_factory=lambda: fallback) is fallback
assert last([], "legacy") == "legacy"
assert last([], None, default_factory=None) is None
expect(ValueError, lambda: last([]))
class Once:
    def __init__(self): self.it = iter([1, 2, 3]); self.iterations = 0
    def __iter__(self):
        self.iterations += 1
        assert self.iterations == 1, "input was restarted"
        return self
    def __next__(self): return next(self.it)
one = Once()
assert last(one, default_factory=factory) == 3 and one.iterations == 1
class ReverseOnly:
    def __init__(self, values): self.values = values
    def __iter__(self): raise AssertionError("forward iteration is forbidden")
    def __reversed__(self): return iter(self.values)
assert last(ReverseOnly([7, 6, 5]), default_factory=factory) == 7
assert calls == []
assert last(ReverseOnly([]), default_factory=factory) == {"fresh": True}
assert calls == ["called"]
calls.clear()
class Untouched:
    def __iter__(self): raise AssertionError("invalid options consumed input")
expect(TypeError, lambda: last(Untouched(), default_factory=42))
expect(ValueError, lambda: last(Untouched(), None, default_factory=factory))
expect(TypeError, lambda: last([], None, factory))
def broken_factory():
    calls.append("error")
    raise RuntimeError("factory failure")
expect(RuntimeError, lambda: last([], default_factory=broken_factory))
assert calls == ["error"]
calls.clear()
def broken_source():
    yield 1
    raise RuntimeError("source failure")
expect(RuntimeError, lambda: last(broken_source(), default_factory=factory))
assert calls == []
print("last lazy-fallback contract passed")
'
